function spreadLetters(s: string): string {
  const count = new Map<string, number>();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  // tiny max-heap on [count, letter]
  const heap: [number, string][] = [];
  const better = (a: [number, string], b: [number, string]) => a[0] > b[0] || (a[0] === b[0] && a[1] < b[1]);
  const push = (x: [number, string]) => {
    heap.push(x);
    for (let i = heap.length - 1; i > 0; ) {
      const p = (i - 1) >> 1;
      if (!better(heap[i], heap[p])) break;
      [heap[i], heap[p]] = [heap[p], heap[i]]; i = p;
    }
  };
  const pop = (): [number, string] => {
    const top = heap[0], last = heap.pop()!;
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ; ) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && better(heap[l], heap[m])) m = l;
        if (r < heap.length && better(heap[r], heap[m])) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]]; i = m;
      }
    }
    return top;
  };
  for (const [ch, c] of count) {
    if (c > Math.ceil(s.length / 2)) return "";
    push([c, ch]);
  }
  const out: string[] = [];
  let held: [number, string] | null = null;
  while (heap.length) {
    const cur = pop();
    out.push(cur[1]);
    if (held && held[0] > 0) push(held);
    held = [cur[0] - 1, cur[1]];
  }
  return out.length === s.length ? out.join("") : "";
}

