function spreadLetters(s: string): string {
  const n = s.length;
  const count = new Map<string, number>();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  let top = s[0];
  for (const [ch, c] of count) if (c > count.get(top)!) top = ch;
  if (count.get(top)! > Math.ceil(n / 2)) return "";
  const out: string[] = new Array(n);
  let pos = 0;
  // the most frequent letter must go first, so its copies never touch
  const order = [top, ...[...count.keys()].filter(ch => ch !== top)];
  for (const ch of order) {
    for (let k = count.get(ch)!; k > 0; k--) {
      if (pos >= n) pos = 1; // even slots used up: switch to odd ones
      out[pos] = ch;
      pos += 2;
    }
  }
  return out.join("");
}

