class Solution:
    def spreadLetters(self, s: str) -> str:
        n = len(s)
        count = Counter(s)
        top = max(count, key=count.get)
        if count[top] > (n + 1) // 2:
            return ""
        out = [""] * n
        pos = 0
        # the most frequent letter must go first, so its copies never touch
        for ch in [top] + [c for c in count if c != top]:
            for _ in range(count[ch]):
                if pos >= n:
                    pos = 1  # even slots used up: switch to odd ones
                out[pos] = ch
                pos += 2
        return "".join(out)

